import{_ as s,o as i,c as a,a0 as t}from"./chunks/framework.1R7PBCUH.js";const k=JSON.parse('{"title":"Removed from process management chapter","description":"","frontmatter":{},"headers":[],"relativePath":"archive/process-management-leftovers.md","filePath":"archive/process-management-leftovers.md"}'),n={name:"archive/process-management-leftovers.md"};function h(o,e,r,l,p,d){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="removed-from-process-management-chapter" tabindex="-1">Removed from process management chapter <a class="header-anchor" href="#removed-from-process-management-chapter" aria-label="Permalink to &quot;Removed from process management chapter&quot;">​</a></h1><h2 id="process-priorities" tabindex="-1">Process priorities <a class="header-anchor" href="#process-priorities" aria-label="Permalink to &quot;Process priorities&quot;">​</a></h2><p>Not all processes are equally important. A video call needs the CPU more urgently than a background backup job. Linux lets you express this with a <strong>nice value</strong>: a number from <code>-20</code> (highest priority) to <code>+19</code> (lowest priority), defaulting to <code>0</code>. The name comes from the idea that a process with a high nice value is being &quot;nice&quot; to others by stepping aside.</p><p>The scheduler uses the nice value to derive an effective priority (<code>PR</code> column in <code>htop</code> and <code>ps</code>). A lower nice value means higher priority and more CPU time. Only root can set a negative nice value; any user can make their own processes <em>less</em> important by raising it.</p><p>Start the CPU-intensive script in the background and inspect its priority:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> u+x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kill-signals.sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./kill-signals.sh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ps</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lp</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Look at the <code>NI</code> column (the nice value) and the <code>PRI</code>/<code>PR</code> column (the effective priority). Both should show the defaults (<code>0</code> and <code>80</code> respectively).</p><h3 id="starting-a-process-with-a-different-priority" tabindex="-1">Starting a process with a different priority <a class="header-anchor" href="#starting-a-process-with-a-different-priority" aria-label="Permalink to &quot;Starting a process with a different priority&quot;">​</a></h3><p>Use <code>nice -n &lt;value&gt;</code> to launch a process with a non-default nice value from the start:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nice</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./kill-signals.sh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ps</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lp</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Open <code>htop</code> and compare the two running instances — you will see different values in the <code>NI</code> column.</p><h3 id="changing-the-priority-of-a-running-process" tabindex="-1">Changing the priority of a running process <a class="header-anchor" href="#changing-the-priority-of-a-running-process" aria-label="Permalink to &quot;Changing the priority of a running process&quot;">​</a></h3><p>Use <code>renice</code> to adjust the nice value of a process that is already running:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">renice</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>This sets the nice value of the given PID to <code>5</code>. You can verify the change immediately in <code>htop</code> or with <code>ps -lp &lt;pid&gt;</code>.</p><p>Note that you can only raise your own processes&#39; nice value (make them less important). Lowering a nice value below <code>0</code> — giving a process higher priority than the default — requires root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> renice</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -5</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><details><summary>Why can only root lower nice values? What could go wrong if any user could give their process the highest priority?</summary><p>If any user could set a negative nice value, a single process could starve every other process on the system — including critical system services — by monopolising the CPU. For example, a malicious or runaway user process at nice <code>-20</code> would be scheduled far ahead of <code>systemd</code>, <code>sshd</code>, and the kernel threads that keep the system responsive. Restricting negative nice values to root ensures that only a privileged administrator can grant elevated scheduling priority, preserving system stability for all users.</p></details><h2 id="concurrency" tabindex="-1">Concurrency <a class="header-anchor" href="#concurrency" aria-label="Permalink to &quot;Concurrency&quot;">​</a></h2><p>When multiple processes run at the same time and access shared resources, things can go wrong in subtle ways. <strong>Concurrency</strong> is the ability of a system to handle multiple tasks that overlap in time — either truly in parallel on multiple CPU cores, or interleaved on a single core. The tricky part is not running tasks simultaneously; it is doing so safely when those tasks share state.</p><p>A <strong>race condition</strong> occurs when the outcome depends on the relative timing of two or more processes. If process A reads a value, and process B reads and updates the same value before A has finished writing, A will overwrite B&#39;s update — one increment is lost. This kind of bug is notoriously hard to reproduce because it depends on exact scheduling order, which varies between runs.</p><h3 id="demonstrating-a-race-condition" tabindex="-1">Demonstrating a race condition <a class="header-anchor" href="#demonstrating-a-race-condition" aria-label="Permalink to &quot;Demonstrating a race condition&quot;">​</a></h3><p><code>counter-unsafe.sh</code> reads a counter from <code>counter.txt</code>, adds one, and writes it back. Launch 50 instances simultaneously and wait for them all to finish:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> counter.txt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> u+x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> counter-unsafe.sh</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">seq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 50</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">do</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ./counter-unsafe.sh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">done</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">wait</span></span></code></pre></div><p>Now wait until all instances have finished and check the final value.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> counter.txt</span></span></code></pre></div><details><summary>If 50 instances each increment the counter once, what would you expect the final value to be? What do you actually see, and why?</summary><p>You would expect <code>50</code>. In practice the value is almost always lower — often significantly so. Each instance reads the current value, computes <code>value + 1</code>, and writes it back. If two instances read the same value before either has written, they both write the same result and one increment is lost. The more instances run in parallel, the worse the loss.</p></details><h3 id="fixing-it-with-a-lock-file" tabindex="-1">Fixing it with a lock file <a class="header-anchor" href="#fixing-it-with-a-lock-file" aria-label="Permalink to &quot;Fixing it with a lock file&quot;">​</a></h3><p><code>counter-safe.sh</code> wraps the same read-increment-write sequence in a <strong>lock file</strong>: before touching the counter it tries to create a file exclusively; if the file already exists, it waits and retries. Only one instance can hold the lock at a time, so the counter is always updated atomically.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> counter.txt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> u+x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> counter-safe.sh</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">seq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 50</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">do</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ./counter-safe.sh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">done</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">wait</span></span></code></pre></div><p>Now wait until all instances have finished and check the final value.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> counter.txt</span></span></code></pre></div><p>The result should now be exactly <code>50</code>.</p><details><summary>What is the downside of a lock file as a mutex? What can go wrong if a script crashes while holding the lock?</summary><p>If the process holding the lock crashes before it can remove the lock file, the file remains on disk. Every other instance will then wait forever — a <strong>deadlock</strong>. A robust solution adds cleanup logic: for example, trapping signals to delete the lock file before exiting, or storing the holder&#39;s PID inside the lock file so other instances can detect whether the holder is still alive.</p></details><h2 id="threads" tabindex="-1">Threads <a class="header-anchor" href="#threads" aria-label="Permalink to &quot;Threads&quot;">​</a></h2><p>A <strong>thread</strong> is a unit of execution that lives inside a process. Where two processes have completely separate address spaces, threads within the same process share the same memory. This makes communication between threads much cheaper than between processes — no file, pipe, or socket needed — but it also means a bug in one thread can corrupt data that every other thread relies on.</p><p>Each thread has its own stack and program counter, but shares the heap, global variables, and open file descriptors with all other threads in the process. The operating system schedules threads the same way it schedules processes, so multiple threads can run truly in parallel on multiple CPU cores.</p><h3 id="race-condition-between-threads" tabindex="-1">Race condition between threads <a class="header-anchor" href="#race-condition-between-threads" aria-label="Permalink to &quot;Race condition between threads&quot;">​</a></h3><p>The race condition from the concurrency section can happen just as easily inside a single process. <code>threads-unsafe.py</code> spawns a number of threads that all increment a shared counter — without any coordination:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> threads-unsafe.py</span></span></code></pre></div><p>The final value will be lower than expected for exactly the same reason as before: one thread reads the counter, another thread reads and updates it before the first has written back, and an increment is lost.</p><h3 id="fixing-it-with-a-lock" tabindex="-1">Fixing it with a lock <a class="header-anchor" href="#fixing-it-with-a-lock" aria-label="Permalink to &quot;Fixing it with a lock&quot;">​</a></h3><p><code>threads-safe.py</code> wraps the increment in a <code>threading.Lock</code>. A lock is the in-memory equivalent of the lock file from the previous section: only one thread can hold it at a time, so the read-modify-write sequence becomes atomic.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> threads-safe.py</span></span></code></pre></div><p>The result is now correct. The lock is more efficient than a lock file — it lives in memory rather than on disk — but the principle is identical: mutual exclusion ensures that only one thread touches the shared state at a time.</p><h3 id="threads-and-i-o" tabindex="-1">Threads and I/O <a class="header-anchor" href="#threads-and-i-o" aria-label="Permalink to &quot;Threads and I/O&quot;">​</a></h3><p>Threads are most valuable when tasks spend time waiting rather than computing. <code>threads-io.py</code> simulates a number of slow network requests, first sequentially and then with one thread per request:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> threads-io.py</span></span></code></pre></div><p>While one thread is blocked waiting for a response, the scheduler runs another thread. The threaded version finishes in roughly the time of a single request rather than the sum of all of them.</p><blockquote><p>When you run <code>threads-io.py</code>, how does the threaded runtime compare to the sequential runtime? Does the speedup grow indefinitely as you add more threads?</p></blockquote>`,50)])])}const u=s(n,[["render",h]]);export{k as __pageData,u as default};
